import React, { useState, useEffect } from 'react';
import { Routes, Route, useLocation } from 'react-router-dom';
import Navigation from './components/Navigation';
import MainFeed from './components/MainFeed';
import Board from './components/Board';
import Timetable from './components/Timetable';
import Marketplace from './components/Marketplace';
import Map from './components/Map';
import MyPage from './components/MyPage';
import SeasonalTheme from './components/SeasonalTheme';
import JapaneseMascot from './components/JapaneseMascot';
import PushNotifications from './components/PushNotifications';
import OfflineSupport from './components/OfflineSupport';
import './App.css';

function App() {
  const [isLoading, setIsLoading] = useState(true);
  const [currentTab, setCurrentTab] = useState('home');
  const [darkMode, setDarkMode] = useState(() => {
    const saved = localStorage.getItem('darkMode');
    return saved ? JSON.parse(saved) : false;
  });
  const [user, setUser] = useState({
    id: 1,
    name: '田中太郎',
    username: '@tanaka_taro',
    avatar: '👤',
    department: '工学部',
    year: 3,
    isAnonymous: false
  });
  const location = useLocation();

  useEffect(() => {
    const path = location.pathname;
    if (path === '/' || path === '/demo3/') setCurrentTab('home');
    else if (path === '/board' || path === '/demo3/board') setCurrentTab('board');
    else if (path === '/timetable' || path === '/demo3/timetable') setCurrentTab('timetable');
    else if (path === '/marketplace' || path === '/demo3/marketplace') setCurrentTab('marketplace');
    else if (path === '/map' || path === '/demo3/map') setCurrentTab('map');
    else if (path === '/mypage' || path === '/demo3/mypage') setCurrentTab('mypage');
  }, [location]);

  useEffect(() => {
    localStorage.setItem('darkMode', JSON.stringify(darkMode));
    document.documentElement.setAttribute('data-theme', darkMode ? 'dark' : 'light');
  }, [darkMode]);

  useEffect(() => {
    // Add mobile-specific error handling
    const handleError = (error) => {
      console.error('Mobile app error:', error);
    };
    
    window.addEventListener('error', handleError);
    window.addEventListener('unhandledrejection', handleError);
    
    // Shorter loading time for mobile
    const timer = setTimeout(() => {
      console.log('App loading completed');
      setIsLoading(false);
    }, 500);
    
    return () => {
      clearTimeout(timer);
      window.removeEventListener('error', handleError);
      window.removeEventListener('unhandledrejection', handleError);
    };
  }, []);

  const toggleDarkMode = () => {
    setDarkMode(prev => !prev);
  };

  if (isLoading) {
    return (
      <div style={{
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100vw',
        height: '100vh',
        background: '#f5f5f5',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 9999
      }}>
        <div style={{ textAlign: 'center' }}>
          <div style={{
            width: '40px',
            height: '40px',
            border: '3px solid #f3f3f3',
            borderTop: '3px solid #007bff',
            borderRadius: '50%',
            animation: 'spin 1s linear infinite',
            margin: '0 auto 16px'
          }}></div>
          <p style={{ margin: 0, fontSize: '14px', fontWeight: 500 }}>読み込み中...</p>
        </div>
      </div>
    );
  }

  // console.log('App rendering with darkMode:', darkMode, 'currentTab:', currentTab);

  return (
    <div className={`app ${darkMode ? 'dark-mode' : ''}`} style={{
      minHeight: '100vh',
      minHeight: '-webkit-fill-available',
      backgroundColor: '#f5f5f5',
      width: '100%',
      display: 'flex',
      justifyContent: 'center',
      position: 'relative',
      WebkitTransform: 'translateZ(0)',
      transform: 'translateZ(0)'
    }}>
      <div className="app-container" style={{
        width: '100%',
        maxWidth: '414px',
        minHeight: '100vh',
        minHeight: '-webkit-fill-available',
        backgroundColor: '#f5f5f5',
        position: 'relative',
        display: 'flex',
        flexDirection: 'column',
        WebkitTransform: 'translateZ(0)',
        transform: 'translateZ(0)'
      }}>
        {/* Dark Mode Toggle */}
        <button 
          className="dark-mode-toggle"
          onClick={toggleDarkMode}
          aria-label={darkMode ? 'ライトモードに切り替え' : 'ダークモードに切り替え'}
        >
          {darkMode ? '☀️' : '🌙'}
        </button>
        
        <main className="main-content" style={{
          flex: 1,
          paddingBottom: '80px',
          overflowX: 'hidden',
          minHeight: '0'
        }}>
          <Routes>
            <Route path="/" element={<MainFeed user={user} setUser={setUser} darkMode={darkMode} />} />
            <Route path="/demo3/" element={<MainFeed user={user} setUser={setUser} darkMode={darkMode} />} />
            <Route path="/board" element={<Board user={user} darkMode={darkMode} />} />
            <Route path="/demo3/board" element={<Board user={user} darkMode={darkMode} />} />
            <Route path="/timetable" element={<Timetable user={user} darkMode={darkMode} />} />
            <Route path="/demo3/timetable" element={<Timetable user={user} darkMode={darkMode} />} />
            <Route path="/marketplace" element={<Marketplace user={user} darkMode={darkMode} />} />
            <Route path="/demo3/marketplace" element={<Marketplace user={user} darkMode={darkMode} />} />
            <Route path="/map" element={<Map user={user} darkMode={darkMode} />} />
            <Route path="/demo3/map" element={<Map user={user} darkMode={darkMode} />} />
            <Route path="/mypage" element={<MyPage user={user} setUser={setUser} darkMode={darkMode} toggleDarkMode={toggleDarkMode} />} />
            <Route path="/demo3/mypage" element={<MyPage user={user} setUser={setUser} darkMode={darkMode} toggleDarkMode={toggleDarkMode} />} />
          </Routes>
        </main>
        <Navigation currentTab={currentTab} darkMode={darkMode} />
        <JapaneseMascot mood="happy" size="medium" position="floating" />
        <PushNotifications />
        <OfflineSupport />
      </div>
    </div>
  );
}

export default App;
